---

### 6. Remediation / Corrected Code
Update the `CheckRequired` function to programmatically validate the relationship between the `rollup-boost` flags:

```go
func CheckRequired(ctx *cli.Context) error {
	for _, f := range requiredFlags {
		if !ctx.IsSet(f.Names()[0]) {
			return fmt.Errorf("flag %s is required", f.Names()[0])
		}
	}

	// Validate mutual exclusion of rollup-boost modes
	boostEnabled := ctx.Bool(RollupBoostEnabled.Name)
	boostNextEnabled := ctx.Bool(RollupBoostNextEnabled.Name)

	if boostEnabled && boostNextEnabled {
		return fmt.Errorf("flags %s and %s are mutually exclusive", RollupBoostEnabled.Name, RollupBoostNextEnabled.Name)
	}

	// Validate conditional requirement for rollup-boost.next-healthcheck-url
	if boostNextEnabled {
		urlVal := ctx.String(RollupBoostNextHealthcheckURL.Name)
		if urlVal == "" {
			return fmt.Errorf("flag %s is required when %s is enabled", RollupBoostNextHealthcheckURL.Name, RollupBoostNextEnabled.Name)
		}
	}

	return opflags.CheckRequiredXor(ctx)
}
```

